function rotate(values, amount) { return [...values.slice(amount), ...values.slice(0, amount)]; }
function makeQuestion(spec, index) {
  const optionTexts = rotate([spec.correct, ...spec.distractors], index % 4);
  const answerOptions = optionTexts.map((text, optionIndex) => ({ id: `o${optionIndex + 1}`, text }));
  const acceptedId = answerOptions.find((option) => option.text === spec.correct).id;
  return { stableId: `central_${spec.stableSuffix}`, version: 1, region: "central", countryScope: spec.countryScope, subregionScope: spec.subregionScope, communityScope: spec.communityScope, category: spec.category, difficulty: ["introductory", "intermediate", "introductory", "intermediate", "advanced"][index % 5], questionKind: "single", questionText: spec.questionText, answerOptions, acceptedAnswers: [[acceptedId]], explanation: spec.explanation, sources: [sources[spec.sourceKey]], reviewer: RESEARCH_REVIEWER, reviewDate: ACCESS_DATE, sensitivityNotes: spec.sensitivityNotes, language: "en", locale: "en", lifecycleStatus: "draft", publishedAt: null, retiredAt: null, validFrom: null, validUntil: null, scoringWeight: 1, imageProvenance: [], audioProvenance: [] };
}
function csvCell(value) { const safe = neutralizeCsvFormula(String(value ?? "")); return /[",\r\n]/.test(safe) ? `"${safe.replaceAll('"', '""')}"` : safe; }
function csv(rows) { return `${rows.map((row) => row.map(csvCell).join(",")).join("\n")}\n`; }
function tally(values) { return [...values.reduce((map, value) => map.set(value, (map.get(value) || 0) + 1), new Map()).entries()].sort(([a], [b]) => a.localeCompare(b)); }
function table(rows) { return rows.map(([name, count]) => `| ${name} | ${count} |`).join("\n"); }

const document = validateQuestionBankDocument({ schemaVersion: "question-bank-v1", questions: specs.map(makeQuestion) });
if (document.questions.length < 65) throw new Error(`expected_at_least_65_candidates_got_${document.questions.length}`);
const legacy = await buildLegacyQuestionBankDocument();
const priorDrafts = await Promise.all(priorDraftFiles.map(async (file) => validateQuestionBankDocument(JSON.parse(await readFile(file, "utf8")))));
const comparisonCatalogue = validateQuestionBankDocument({ schemaVersion: "question-bank-v1", questions: [...legacy.questions, ...priorDrafts.flatMap((item) => item.questions)] });
const duplicateReport = previewQuestionBankImport(document, comparisonCatalogue);
const sourceEntries = Object.entries(sources);
const sourceCounts = new Map(sourceEntries.map(([key]) => [key, specs.filter((spec) => spec.sourceKey === key).length]));
const difficultyCounts = tally(document.questions.map((question) => question.difficulty));
const categoryCounts = tally(document.questions.map((question) => question.category));
const countryOccurrences = tally(document.questions.flatMap((question) => question.countryScope.split("; ")));
const sensitiveQuestions = document.questions.filter((question) => question.sensitivityNotes);

const reviewRows = [["stableId", "version", "countryScope", "subregionScope", "communityScope", "category", "difficulty", "questionText", "acceptedAnswer", "lifecycleStatus", "specialistReviewRequired", "sensitivityNotes", "sourceTitle", "sourceUrl", "humanDecision", "humanReviewer", "humanReviewDate", "humanReviewNotes"]];
for (const question of document.questions) {
  const accepted = question.acceptedAnswers[0].map((id) => question.answerOptions.find((option) => option.id === id).text).join(" | ");
  reviewRows.push([question.stableId, question.version, question.countryScope, question.subregionScope, question.communityScope, question.category, question.difficulty, question.questionText, accepted, question.lifecycleStatus, "yes", question.sensitivityNotes, question.sources[0].title, question.sources[0].urlOrReference, "pending", "", "", ""]);
}
const sourceRows = [["sourceId", "title", "organisationOrAuthor", "urlOrReference", "sourceType", "accessDate", "candidateCount", "relevantClaim"]];
sourceEntries.forEach(([key, item], index) => sourceRows.push([`CA-S${String(index + 1).padStart(2, "0")}`, item.title, item.organisationOrAuthor, item.urlOrReference, item.sourceType, item.accessDate, sourceCounts.get(key), item.relevantClaim]));

const coverage = `# Central Africa draft question-bank coverage\n\nGenerated ${ACCESS_DATE}. These ${document.questions.length} records are research candidates only. All remain draft, excluded from selection, and queued for human cultural review. The application scope is rainforest, rivers and kingdoms, while every record preserves specific country and community scope.\n\n## Totals\n\n- Candidates: ${document.questions.length}\n- Lifecycle: draft (${document.questions.length})\n- Unique authoritative sources: ${sourceEntries.length}\n- Specialist-review flags: ${sensitiveQuestions.length}\n- Media assets: 0\n\n## Difficulty\n\n| Difficulty | Count |\n| --- | ---: |\n${table(difficultyCounts)}\n\n## Category\n\n| Category | Count |\n| --- | ---: |\n${table(categoryCounts)}\n\n## Country occurrence\n\nCross-border questions count once for each named country.\n\n| Country | Candidate occurrences |\n| --- | ---: |\n${table(countryOccurrences)}\n\n## Topic coverage\n\nThe pack includes foodways, language, music, theatre, visual arts, festivals, governance, community transmission, marriage change, history, archaeology, geography, ecology and contemporary safeguarding. No proverb was added because the run did not find attribution and translation evidence strong enough for draft inclusion.\n`;

const underrepresented = `# Central Africa under-representation and classification report\n\nCounts measure research coverage, not population, cultural importance or editorial priority.\n\n## Classification decisions\n\n- **Angola:** included because Mbanza Kongo, Sona and cross-border Lunda Cokwe histories fit the application's Central edition; Angola also has strong Southern African connections.\n- **Cameroon:** included in this product edition while acknowledging common West/Central and Sahelian classifications. Cross-border Kapsiki/Higi material names Nigeria and is not duplicated from the West pack.\n- **Chad:** included for the established Central edition, with Saharan and Sahelian connections stated precisely.\n- **Burundi and Rwanda:** not duplicated here because the repository's East Africa pack already covers them, despite some Central Africa classifications.\n- **São Tomé and Príncipe:** represented through Tchiloli; broader island food, language and everyday-life coverage needs more locally authored institutional sources.\n- **Equatorial Guinea:** current coverage is limited to the state's UNESCO Tentative List. Tentative status is never described as inscription. Living Fang, Bubi, Ndowe, Annobonese and other community practices remain underrepresented pending locally led sources and review.\n\n## Known gaps\n\n- Central African Republic has strong Aka music and Sangha ecology coverage but needs locally authored sources on urban life, foodways, languages and communities beyond the south-west.\n- Congo and DRC need more contemporary sources beyond rumba, protected landscapes and museum histories.\n- Wedding coverage is deliberately narrow: two Kapsiki/Higi research candidates demonstrate change and variation; no marriage payment or ceremony is generalized across countries.\n- Greetings and proverbs were omitted because translation, register and attribution require fluent community reviewers and stronger locally authored sources.\n- Food coverage focuses on cross-border cassava and Gnetum variation. Household recipes and claims of national ownership were avoided.\n`;

const issueLog = `# Central Africa cultural-review issue log\n\nAll ${document.questions.length} candidates remain draft. The word approved inside a source record means the reference passed the software source gate; it does not mean cultural approval.\n\n## Specialist review queue (${sensitiveQuestions.length})\n\n${sensitiveQuestions.map((question) => `- **${question.stableId}:** ${question.sensitivityNotes}`).join("\n")}\n\n## Collection-wide review questions\n\n- Confirm names, diacritics, language register, country scope and community self-identification with reviewers from the named communities.\n- Remove any detail that community reviewers identify as restricted, sacred or unsuitable for a general-audience quiz.\n- Review colonial, enslavement, protected-area and museum-source framing for power imbalance and historical harm.\n- Confirm that Indigenous rights and present-day communities are not displaced by conservation or archaeological narratives.\n- Review marriage and gender wording as contextual and changing, never universal or prescriptive.\n- Recheck every live source and factual claim on the human-review date.\n`;

const duplicateAnalysis = `# Central Africa duplicate and near-duplicate analysis\n\nCompared ${document.questions.length} Central Africa drafts against each other, the verified ${legacy.questions.length}-question catalogue, ${priorDrafts[0].questions.length} West Africa drafts, ${priorDrafts[1].questions.length} East Africa drafts and ${priorDrafts[2].questions.length} North Africa drafts using the Prompt 20 preview.\n\n- Exact duplicate question texts: ${duplicateReport.exactDuplicates.length}\n- Token near-duplicate pairs: ${duplicateReport.nearDuplicates.length}\n- Writes performed: ${duplicateReport.writesPerformed}\n\n## Exact duplicates\n\n${duplicateReport.exactDuplicates.length ? duplicateReport.exactDuplicates.map((item) => `- ${item}`).join("\n") : "None detected."}\n\n## Near duplicates\n\n${duplicateReport.nearDuplicates.length ? duplicateReport.nearDuplicates.map((item) => `- ${item.left} / ${item.right}: ${item.similarity}`).join("\n") : "None detected at the configured threshold."}\n\nHuman reviewers must still assess conceptual overlap involving Mbanza Kongo, Congolese rumba, Mvet, Congo Basin ecology, cassava and Central African arts because automated wording checks cannot establish cultural distinctness.\n`;

